import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:watcher/watcher.dart';
import 'package:permission_handler/permission_handler.dart';
import 'package:flutter_markdown/flutter_markdown.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const SayCheeseAgentApp());
}

class EjercicioResuelto {
  final String id;
  final String? rutaImagen;
  final String? miniaturaBase64;
  final DateTime fecha;
  String autor;
  String modeloUsado;
  String? solucion;
  bool procesando;

  EjercicioResuelto({
    required this.id,
    this.rutaImagen,
    this.miniaturaBase64,
    required this.fecha,
    this.autor = 'Local',
    required this.modeloUsado,
    this.solucion,
    this.procesando = true,
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'rutaImagen': rutaImagen,
        'miniaturaBase64': miniaturaBase64,
        'fecha': fecha.toIso8601String(),
        'autor': autor,
        'modeloUsado': modeloUsado,
        'solucion': solucion,
        'procesando': procesando,
      };

  factory EjercicioResuelto.fromJson(Map<String, dynamic> json) =>
      EjercicioResuelto(
        id: json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        rutaImagen: json['rutaImagen'],
        miniaturaBase64: json['miniaturaBase64'],
        fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
        autor: json['autor'] ?? 'Compañero',
        modeloUsado: json['modeloUsado'] ?? 'gemini-2.5-flash',
        solucion: json['solucion'],
        procesando: json['procesando'] ?? false,
      );
}

class SayCheeseAgentApp extends StatelessWidget {
  const SayCheeseAgentApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'SayCheese Agent 4.1',
      debugShowCheckedModeBanner: false,
      theme: ThemeData.dark(useMaterial3: true).copyWith(
        colorScheme: ColorScheme.fromSeed(
          seedColor: Colors.deepPurpleAccent,
          brightness: Brightness.dark,
        ),
      ),
      home: const HomeScreen(),
    );
  }
}

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  int _pestanaActual = 0;
  bool _agenteActivo = false;
  StreamSubscription<WatchEvent>? _watcherSub;
  Timer? _syncTimer;
  final List<EjercicioResuelto> _historial = [];

  final String _rutaCarpeta = '/storage/emulated/0/Pictures/SayCheese';
  final String _rutaRespaldoFijo = '/storage/emulated/0/Pictures/SayCheese/.saycheese_historial_v4.json';

  String _apiKey = const String.fromEnvironment(
    'GEMINI_API_KEY',
    defaultValue: '',
  );

  // Selector de modelos sin forzar pro-preview
  String _modeloSeleccionado = 'gemini-2.5-flash';
  final List<String> _modelosDisponibles = [
    'gemini-2.5-flash',
    'gemini-3-flash-preview',
    'gemini-3.1-pro-preview',
    'gemini-2.5-pro',
  ];

  // Sala compartida entre 2 personas
  String _codigoSala = '';
  String _aliasUsuario = 'Yo';
  bool _sincronizando = false;

  @override
  void initState() {
    super.initState();
    _inicializarTodo();
  }

  Future<void> _inicializarTodo() async {
    await _iniciarAgente();
    await _cargarDatosLocales();
    _syncTimer = Timer.periodic(const Duration(seconds: 10), (_) {
      if (_codigoSala.isNotEmpty) {
        _sincronizarSalaCompartida(silencioso: true);
      }
    });
  }

  Future<void> _cargarDatosLocales() async {
    final prefs = await SharedPreferences.getInstance();
    final savedKey = prefs.getString('gemini_api_key');
    if (savedKey != null && savedKey.isNotEmpty) {
      _apiKey = savedKey;
    }

    final savedModel = prefs.getString('gemini_model');
    if (savedModel != null && savedModel.isNotEmpty) {
      if (!_modelosDisponibles.contains(savedModel)) {
        _modelosDisponibles.insert(0, savedModel);
      }
      _modeloSeleccionado = savedModel;
    }

    _codigoSala = prefs.getString('sala_compartida') ?? '';
    _aliasUsuario = prefs.getString('alias_usuario') ?? 'Yo';

    List<EjercicioResuelto> cargados = [];

    // 1. Intentar leer desde SharedPreferences (JSON unificado + lista)
    try {
      final rawUnificado = prefs.getString('historial_json_completo_v4');
      if (rawUnificado != null && rawUnificado.isNotEmpty) {
        final List listaRaw = jsonDecode(rawUnificado);
        cargados = listaRaw
            .map((e) => EjercicioResuelto.fromJson(e as Map<String, dynamic>))
            .toList();
      }
    } catch (_) {}

    if (cargados.isEmpty) {
      final historialLista = prefs.getStringList('historial_ejercicios_v4') ??
          prefs.getStringList('historial_ejercicios_v3') ??
          [];
      for (final itemStr in historialLista) {
        try {
          cargados.add(EjercicioResuelto.fromJson(jsonDecode(itemStr)));
        } catch (_) {}
      }
    }

    // 2. Respaldo fisico en la carpeta SayCheese por si el sistema limpia preferencias
    if (cargados.isEmpty) {
      try {
        final file = File(_rutaRespaldoFijo);
        if (await file.exists()) {
          final contenido = await file.readAsString();
          if (contenido.isNotEmpty) {
            final List listaRaw = jsonDecode(contenido);
            cargados = listaRaw
                .map((e) => EjercicioResuelto.fromJson(e as Map<String, dynamic>))
                .toList();
          }
        }
      } catch (_) {}
    }

    if (mounted) {
      setState(() {
        _historial
          ..clear()
          ..addAll(cargados);
      });
    }

    if (_codigoSala.isNotEmpty) {
      _sincronizarSalaCompartida(silencioso: true);
    }
  }

  Future<void> _guardarHistorialLocal() async {
    final listaMap = _historial.map((e) => e.toJson()).toList();
    final jsonCompleto = jsonEncode(listaMap);

    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('historial_json_completo_v4', jsonCompleto);
      final listaStrings = _historial.map((e) => jsonEncode(e.toJson())).toList();
      await prefs.setStringList('historial_ejercicios_v4', listaStrings);
    } catch (_) {}

    try {
      final file = File(_rutaRespaldoFijo);
      await file.writeAsString(jsonCompleto, flush: true);
    } catch (_) {}
  }

  Uri _obtenerUrlSala(String sala) {
    final hashSala = base64Url
        .encode(utf8.encode('saycheese_room_$sala'))
        .replaceAll('=', '');
    return Uri.parse('https://kvdb.io/A6Xy9kLmN2pQrStUvWxYz/$hashSala');
  }

  Future<void> _subirASalaCompartida() async {
    if (_codigoSala.trim().isEmpty) return;
    try {
      final resueltos = _historial
          .where((e) => !e.procesando && e.solucion != null)
          .take(20)
          .map((e) => {
                'id': e.id,
                'fecha': e.fecha.toIso8601String(),
                'autor': e.autor,
                'modeloUsado': e.modeloUsado,
                'solucion': e.solucion,
                'procesando': false,
              })
          .toList();

      await http.post(
        _obtenerUrlSala(_codigoSala.trim()),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode(resueltos),
      );
    } catch (_) {}
  }

  Future<void> _sincronizarSalaCompartida({bool silencioso = false}) async {
    if (_codigoSala.trim().isEmpty) return;
    if (!silencioso && mounted) setState(() => _sincronizando = true);

    try {
      final res = await http.get(_obtenerUrlSala(_codigoSala.trim()));
      if (res.statusCode == 200 && res.body.isNotEmpty) {
        final listaRemota = jsonDecode(res.body) as List;
        bool huboCambios = false;

        for (final raw in listaRemota) {
          final itemRemoto =
              EjercicioResuelto.fromJson(raw as Map<String, dynamic>);
          final existeIdx =
              _historial.indexWhere((local) => local.id == itemRemoto.id);
          if (existeIdx == -1) {
            _historial.add(itemRemoto);
            huboCambios = true;
          } else if (_historial[existeIdx].solucion != itemRemoto.solucion &&
              itemRemoto.solucion != null) {
            _historial[existeIdx].solucion = itemRemoto.solucion;
            _historial[existeIdx].modeloUsado = itemRemoto.modeloUsado;
            _historial[existeIdx].procesando = false;
            huboCambios = true;
          }
        }

        if (huboCambios) {
          _historial.sort((a, b) => b.fecha.compareTo(a.fecha));
          if (mounted) setState(() {});
          await _guardarHistorialLocal();
        }
      }
      await _subirASalaCompartida();
    } catch (_) {
    } finally {
      if (!silencioso && mounted) setState(() => _sincronizando = false);
    }
  }

  Future<void> _abandonarSala() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.remove('sala_compartida');
    if (mounted) {
      setState(() {
        _codigoSala = '';
        _sincronizando = false;
      });
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Has abandonado la sala compartida.')),
      );
    }
  }

  Future<void> _iniciarAgente() async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
    ].request();

    final dir = Directory(_rutaCarpeta);
    if (!await dir.exists()) {
      try {
        await dir.create(recursive: true);
      } catch (_) {}
    }

    final watcher = DirectoryWatcher(_rutaCarpeta);
    _watcherSub = watcher.events.listen((event) {
      final pathLower = event.path.toLowerCase();
      if (event.type == ChangeType.ADD &&
          (pathLower.endsWith('.jpg') ||
              pathLower.endsWith('.jpeg') ||
              pathLower.endsWith('.png'))) {
        _procesarNuevaFoto(File(event.path));
      }
    });

    if (mounted) setState(() => _agenteActivo = true);
  }

  Future<void> _procesarNuevaFoto(File archivoImagen) async {
    await Future.delayed(const Duration(seconds: 2));

    final prefs = await SharedPreferences.getInstance();
    final modeloActual = prefs.getString('gemini_model') ?? _modeloSeleccionado;
    final aliasActual = prefs.getString('alias_usuario') ?? _aliasUsuario;

    final nuevoItem = EjercicioResuelto(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      rutaImagen: archivoImagen.path,
      fecha: DateTime.now(),
      autor: aliasActual,
      modeloUsado: modeloActual,
    );

    if (mounted) {
      setState(() {
        _modeloSeleccionado = modeloActual;
        _aliasUsuario = aliasActual;
        _historial.insert(0, nuevoItem);
      });
    }
    await _guardarHistorialLocal();

    await _intentarResolver(nuevoItem);
  }

  Future<void> _intentarResolver(EjercicioResuelto item) async {
    if (item.rutaImagen == null) return;

    final prefs = await SharedPreferences.getInstance();
    final modeloElegido = prefs.getString('gemini_model') ?? _modeloSeleccionado;
    final aliasElegido = prefs.getString('alias_usuario') ?? _aliasUsuario;

    if (mounted) {
      setState(() {
        _modeloSeleccionado = modeloElegido;
        _aliasUsuario = aliasElegido;
        item.modeloUsado = modeloElegido;
        item.autor = aliasElegido;
        item.procesando = true;
        item.solucion = null;
      });
    }
    await _guardarHistorialLocal();

    try {
      final respuesta =
          await _llamarGeminiEstricto(File(item.rutaImagen!), modeloElegido);
      if (mounted) {
        setState(() {
          item.solucion = _limpiarRespuestaMarkdown(respuesta);
          item.modeloUsado = modeloElegido;
          item.procesando = false;
        });
      }
      await _guardarHistorialLocal();
      await _subirASalaCompartida();
    } catch (e) {
      if (mounted) {
        setState(() {
          item.solucion = 'Error con el modelo $modeloElegido: $e';
          item.procesando = false;
        });
      }
      await _guardarHistorialLocal();
    }
  }

  // Elimina bloques de codigo y sangrias para que nunca salga el recuadro celeste
  String _limpiarRespuestaMarkdown(String raw) {
    var limpio = raw.replaceAll('```markdown', '').replaceAll('```', '');
    final lineas = limpio.split('\n');
    final procesadas = lineas.map((linea) {
      if (linea.startsWith('    ') &&
          !linea.trimLeft().startsWith('*') &&
          !linea.trimLeft().startsWith('-') &&
          !RegExp(r'^\d+\.').hasMatch(linea.trimLeft())) {
        return linea.trimLeft();
      }
      return linea;
    }).toList();
    return procesadas.join('\n').trim();
  }

  Future<String> _llamarGeminiEstricto(File imagen, String modelo) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty) {
      throw Exception(
          'Configura tu Gemini API Key (AIzaSy...) en el icono de engranaje superior.');
    }

    final bytes = await imagen.readAsBytes();
    final base64Image = base64Encode(bytes);
    final modActual = modelo.trim();

    final url = Uri.parse(
      'https://generativelanguage.googleapis.com/v1beta/models/$modActual:generateContent?key=$keyLimpia',
    );

    final Map<String, dynamic> payload = {
      "contents": [
        {
          "parts": [
            {
              "text":
                  "Resuelve todos los ejercicios de esta hoja paso a paso. Usa formato Markdown claro, enumera cada ejercicio y destaca el resultado final en negrita (NUNCA uses bloques de codigo ni sangrias de 4 espacios para el resultado final)."
            },
            {
              "inline_data": {
                "mime_type": "image/jpeg",
                "data": base64Image,
              }
            }
          ]
        }
      ],
    };

    if (modActual.contains('2.5')) {
      payload["generationConfig"] = {
        "thinkingConfig": {"thinkingBudget": 4096}
      };
    }

    http.Response? response;
    for (int i = 0; i < 3; i++) {
      try {
        response = await http.post(
          url,
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode(payload),
        );
        break;
      } catch (e) {
        if (i == 2) rethrow;
        await Future.delayed(const Duration(seconds: 2));
      }
    }

    if (response!.statusCode == 200) {
      final data = jsonDecode(response.body);
      final parts = data['candidates'][0]['content']['parts'] as List;
      final textPart = parts.lastWhere(
        (p) => p.containsKey('text') && p['thought'] != true,
        orElse: () => parts.last,
      );
      return textPart['text'];
    } else {
      throw Exception(
          'Codigo ${response.statusCode} en $modActual: ${response.body}');
    }
  }

