    return Padding(
      padding: const EdgeInsets.all(16.0),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Card(
            child: ListTile(
              leading: Icon(
                _agenteActivo ? Icons.check_circle : Icons.error,
                color: _agenteActivo ? Colors.greenAccent : Colors.orange,
                size: 36,
              ),
              title: Text(_agenteActivo
                  ? 'Vigilando carpeta SayCheese'
                  : 'Iniciando agente...'),
              subtitle: Text(
                  'Modelo fijado: $_modeloSeleccionado\nRuta: $_rutaCarpeta'),
              trailing: IconButton(
                icon: const Icon(Icons.tune),
                onPressed: _mostrarDialogoConfiguracion,
              ),
            ),
          ),
          const SizedBox(height: 8),
          Card(
            color: _codigoSala.isNotEmpty
                ? Colors.deepPurple.withOpacity(0.3)
                : null,
            child: ListTile(
              leading: Icon(
                Icons.people_alt_rounded,
                color:
                    _codigoSala.isNotEmpty ? Colors.greenAccent : Colors.grey,
              ),
              title: Text(_codigoSala.isNotEmpty
                  ? 'Sala: $_codigoSala (Alias: $_aliasUsuario)'
                  : 'Modo Individual (Alias: $_aliasUsuario)'),
              subtitle: Text(_codigoSala.isNotEmpty
                  ? 'Sincronizando respuestas cada 10s'
                  : 'Toca aqui para cambiar tu nombre o unirte a una sala'),
              trailing: _codigoSala.isNotEmpty
                  ? IconButton(
                      icon: const Icon(Icons.logout, color: Colors.redAccent),
                      tooltip: 'Abandonar sala',
                      onPressed: _abandonarSala,
                    )
                  : const Icon(Icons.arrow_forward_ios, size: 16),
              onTap: _mostrarDialogoSalaCompartida,
            ),
          ),
          const SizedBox(height: 20),
          Text(
            'Procesando en segundo plano (${enCola.length})',
            style: Theme.of(context).textTheme.titleMedium,
          ),
          const SizedBox(height: 12),
          Expanded(
            child: enCola.isEmpty
                ? const Center(
                    child: Text(
                      'Sube o mueve una foto a la carpeta "SayCheese" y se resolvera usando estrictamente el modelo que elegiste.',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: Colors.grey),
                    ),
                  )
                : ListView.builder(
                    itemCount: enCola.length,
                    itemBuilder: (context, index) {
                      final item = enCola[index];
                      return Card(
                        child: ListTile(
                          leading: item.rutaImagen != null
                              ? Image.file(
                                  File(item.rutaImagen!),
                                  width: 50,
                                  height: 50,
                                  fit: BoxFit.cover,
                                  errorBuilder: (_, __, ___) =>
                                      const Icon(Icons.image),
                                )
                              : const Icon(Icons.cloud_download),
                          title:
                              Text('Resolviendo con ${item.modeloUsado}...'),
                          subtitle: const LinearProgressIndicator(),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildVistaSoluciones(List<EjercicioResuelto> resueltos) {
    return Column(
      children: [
        if (_codigoSala.isNotEmpty)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
            color: Colors.deepPurple.withOpacity(0.25),
            child: Row(
              children: [
                Expanded(
                  child: Text(
                    'Sala: $_codigoSala',
                    style: const TextStyle(
                        fontSize: 13, fontWeight: FontWeight.bold),
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
                TextButton.icon(
                  icon: const Icon(Icons.sync, size: 16),
                  label: const Text('Actualizar', style: TextStyle(fontSize: 12)),
                  onPressed: () => _sincronizarSalaCompartida(),
                ),
                TextButton.icon(
                  style: TextButton.styleFrom(foregroundColor: Colors.redAccent),
                  icon: const Icon(Icons.logout, size: 16),
                  label: const Text('Salir', style: TextStyle(fontSize: 12)),
                  onPressed: _abandonarSala,
                ),
              ],
            ),
          ),
        Expanded(
          child: resueltos.isEmpty
              ? const Center(
                  child: Text('Aun no hay hojas resueltas en este apartado.'),
                )
              : ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: resueltos.length,
                  itemBuilder: (context, index) {
                    final item = resueltos[index];
                    final tieneFotoLocal = item.rutaImagen != null &&
                        File(item.rutaImagen!).existsSync();
                    return Card(
                      margin: const EdgeInsets.only(bottom: 12),
                      child: ListTile(
                        contentPadding: const EdgeInsets.all(12),
                        leading: ClipRRect(
                          borderRadius: BorderRadius.circular(8),
                          child: tieneFotoLocal
                              ? Image.file(
                                  File(item.rutaImagen!),
                                  width: 60,
                                  height: 60,
                                  fit: BoxFit.cover,
                                  errorBuilder: (_, __, ___) =>
                                      const Icon(Icons.image, size: 40),
                                )
                              : Container(
                                  width: 60,
                                  height: 60,
                                  color: Colors.deepPurple.withOpacity(0.3),
                                  child:
                                      const Icon(Icons.cloud_done, size: 32),
                                ),
                        ),
                        title: Text(
                            'Hoja #${resueltos.length - index} • ${item.autor}'),
                        subtitle: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Modelo: ${item.modeloUsado}',
                              style: const TextStyle(
                                  fontSize: 11,
                                  color: Colors.deepPurpleAccent),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              item.solucion ?? '',
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ],
                        ),
                        trailing: tieneFotoLocal
                            ? IconButton(
                                icon: const Icon(Icons.refresh),
                                tooltip:
                                    'Reintentar con $_modeloSeleccionado',
                                onPressed: () => _intentarResolver(item),
                              )
                            : const Icon(Icons.arrow_forward_ios, size: 16),
                        onTap: () async {
                          await Navigator.push(
                            context,
                            MaterialPageRoute(
                              builder: (_) => DetalleSolucionScreen(
                                ejercicio: item,
                                onReintentar: tieneFotoLocal
                                    ? () {
                                        Navigator.pop(context);
                                        _intentarResolver(item);
                                      }
                                    : null,
                              ),
                            ),
                          );
                        },
                      ),
                    );
                  },
                ),
        ),
      ],
    );
  }
}

class DetalleSolucionScreen extends StatelessWidget {
  final EjercicioResuelto ejercicio;
  final VoidCallback? onReintentar;

  const DetalleSolucionScreen({
    super.key,
    required this.ejercicio,
    this.onReintentar,
  });

  @override
  Widget build(BuildContext context) {
    final tieneFotoLocal = ejercicio.rutaImagen != null &&
        File(ejercicio.rutaImagen!).existsSync();

    // Estilo Markdown personalizado en modo oscuro para eliminar el cuadro azul claro ilegible
    final markdownDarkSheet =
        MarkdownStyleSheet.fromTheme(Theme.of(context)).copyWith(
      p: const TextStyle(color: Colors.white, fontSize: 15, height: 1.45),
      h1: const TextStyle(
          color: Colors.white, fontSize: 20, fontWeight: FontWeight.bold),
      h2: const TextStyle(
          color: Colors.white, fontSize: 18, fontWeight: FontWeight.bold),
      h3: const TextStyle(
          color: Colors.deepPurpleAccent,
          fontSize: 16,
          fontWeight: FontWeight.bold),
      strong: const TextStyle(
          color: Colors.amberAccent, fontWeight: FontWeight.bold),
      blockquote: const TextStyle(color: Colors.white, fontSize: 15),
      blockquoteDecoration: BoxDecoration(
        color: const Color(0xFF252336),
        borderRadius: BorderRadius.circular(8),
        border: const Border(
          left: BorderSide(color: Colors.deepPurpleAccent, width: 4),
        ),
      ),
      code: const TextStyle(
        color: Colors.white,
        backgroundColor: Color(0xFF252336),
        fontFamily: 'monospace',
        fontSize: 14,
      ),
      codeblockPadding: const EdgeInsets.all(14),
      codeblockDecoration: BoxDecoration(
        color: const Color(0xFF252336),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(
            color: Colors.deepPurpleAccent.withOpacity(0.5), width: 1),
      ),
    );

    return Scaffold(
      appBar: AppBar(
        title: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Solucion (${ejercicio.autor})',
                style: const TextStyle(fontSize: 17)),
            Text(
              'Resuelto con: ${ejercicio.modeloUsado}',
              style:
                  const TextStyle(fontSize: 11, color: Colors.greenAccent),
            ),
          ],
        ),
        actions: [
          if (onReintentar != null)
            IconButton(
              icon: const Icon(Icons.refresh),
              tooltip: 'Reintentar con el modelo actual',
              onPressed: onReintentar,
            ),
        ],
      ),
      body: Column(
        children: [
          if (tieneFotoLocal)
            SizedBox(
              height: 180,
              width: double.infinity,
              child: InteractiveViewer(
                child: Image.file(
                  File(ejercicio.rutaImagen!),
                  fit: BoxFit.contain,
                  errorBuilder: (_, __, ___) =>
                      const Center(child: Icon(Icons.broken_image, size: 48)),
                ),
              ),
            ),
          const Divider(height: 1),
          Expanded(
            child: Markdown(
              data: ejercicio.solucion ?? 'Sin respuesta.',
              selectable: true,
              styleSheet: markdownDarkSheet,
            ),
          ),
        ],
      ),
    );
  }
}
